contract MockSavings is ISavingsContractV2 {
    IERC20 public underlying;
    uint256 public exchangeRate = 1e18;
    uint256 private totalCredits;
    mapping(address => uint256) private balances;

    constructor() {
        underlying = IERC20(address(new MockERC20()));
    }

    function depositSavings(uint256 amount) external returns (uint256 creditsIssued) {
        creditsIssued = amount;
        totalCredits += creditsIssued;
        balances[msg.sender] += creditsIssued;
        return creditsIssued;
    }

    function redeemUnderlying(uint256 amount) external returns (uint256 creditsBurned) {
        creditsBurned = amount;
        totalCredits -= creditsBurned;
        balances[msg.sender] -= creditsBurned;
        return creditsBurned;
    }

    function creditBalances(address) external view returns (uint256) { return 0; }
    function depositInterest(uint256) external {}
    function depositSavings(uint256, address) external returns (uint256) { return 0; }
    function redeemCredits(uint256) external returns (uint256) { return 0; }
    function redeem(uint256) external returns (uint256) { return 0; }
    function balanceOfUnderlying(address) external view returns (uint256) { return 0; }
    function underlyingToCredits(uint256) external pure returns (uint256) { return 0; }
    function creditsToUnderlying(uint256) external pure returns (uint256) { return 0; }
}

contract MockERC20 is IERC20 {
    string public name = "Mock";
    string public symbol = "MCK";
    uint8 public decimals = 18;
    uint256 public totalSupply = 1e30;
    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;

    constructor() {
        balanceOf[msg.sender] = totalSupply;
    }

    function transfer(address to, uint256 amount) external returns (bool) {
        balanceOf[msg.sender] -= amount;
        balanceOf[to] += amount;
        return true;
    }

    function approve(address spender, uint256 amount) external returns (bool) {
        allowance[msg.sender][spender] = amount;
        return true;
    }

    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        allowance[from][msg.sender] -= amount;
        balanceOf[from] -= amount;
        balanceOf[to] += amount;
        return true;
    }
}

