import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0); }
    function testFuzz_property(uint256 amount1, uint256 amount2, address user) public {
        vm.assume(user != address(0) && user != address(c));
        amount1 = bound(amount1, 1, 1e24);
        amount2 = bound(amount2, 1, 1e24);

        // Setup user with mAsset and approve
        vm.prank(user);
        deal(address(c.mAsset()), user, amount1 + amount2, true);
        vm.prank(user);
        IERC20(c.mAsset()).approve(address(c), amount1 + amount2);

        // First supply and redeem to set initial state
        vm.prank(user);
        c.supplyTokenTo(amount1, user);

        // Call approveMax
        c.approveMax();

        uint256 assetsBefore = c.mAsset().balanceOf(address(c));
        uint256 creditsBefore = c.imBalances(user);
        uint256 exchangeRate = ISavingsContractV2(address(c.savings())).exchangeRate();

        (bool success, uint256 returnedAssets) = address(c).call(abi.encodeWithSelector(c.redeemToken.selector, amount2));

        uint256 assetsAfter = c.mAsset().balanceOf(address(c));
        uint256 creditsAfter = c.imBalances(user);

        assertTrue(success && (assetsAfter - assetsBefore + returnedAssets == (creditsBefore - creditsAfter) * exchangeRate / 1e18));
    }
}

