pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0); }
    function testFuzz_property(uint256 mAssetAmount) public {
        vm.assume(c.mAsset() != address(0));
        vm.assume(c.savings() != address(0));
        vm.assume(mAssetAmount > 0 && mAssetAmount <= 1e30);

        // Deploy a mock savings contract to avoid reverts
        // But the test must use the deployed contract as-is; we can't change setUp.
        // Instead, we can only test public/external behavior.
        // The difference is that M returns mAssetsActual but does not transfer the tokens.
        // We can check that after redeemToken, the contract's mAsset balance is unchanged.

        uint256 balanceBefore = IERC20(c.mAsset()).balanceOf(address(c));
        uint256 returned = c.redeemToken(mAssetAmount);
        uint256 balanceAfter = IERC20(c.mAsset()).balanceOf(address(c));
        // In P, tokens are transferred out, so balance decreases by returned.
        // In M, tokens stay, so balance decreases by 0 (or different).
        // Rule: balanceBefore - balanceAfter == returned (if not reverted)
        assertTrue(balanceBefore - balanceAfter == returned, "balance change != returned");
    }
}

