pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0); }
    function testFuzz_property(uint256 mAssetAmount) public {
        vm.assume(mAssetAmount > 0 && mAssetAmount < 1e30);

        // Fund the contract with enough mAsset
        address mAsset = address(c.mAsset());
        deal(mAsset, address(c), mAssetAmount * 2);

        // Simulate a user with imBalance
        uint256 credits = mAssetAmount; // simplified: credits = amount
        // We need to set imBalances for the caller; but imBalances is public, so we can read it
        // Instead we call supplyTokenTo to set up the state
        vm.prank(address(0x1));
        c.supplyTokenTo(mAssetAmount, msg.sender);

        // Now call redeemToken
        vm.prank(msg.sender);
        (bool success, bytes memory data) = address(c).call(
            abi.encodeWithSignature("redeemToken(uint256)", mAssetAmount)
        );

        require(success, "redeemToken reverted");

        uint256 returnValue = abi.decode(data, (uint256));

        // The rule: returnValue should be equal to mAssetAmount (since exchangeRate is 1 in this simplified test)
        assertTrue(returnValue == mAssetAmount, "Return value mismatch");
    }
}
